body.value:
(* Linear scaling of the 4-20mA raw signal to engineering units. *)
PV := Raw_Signal * Scaling_Slope + Scaling_Offset;
(* Wire-break style fault: a healthy 4-20mA loop never drops below ~2mA. *)
General_Fault := Alarm_Enable AND (Raw_Signal < 2.0);
High_Alarm := Alarm_Enable AND (PV > PV_High);
Low_Alarm := Alarm_Enable AND (PV < PV_Low);

Bool_Out := Bool_In;
Alarm_Active := (Alarm_OnTrue AND Bool_In) OR (Alarm_OnFalse AND NOT Bool_In);
IF Reset_Latch THEN
    Latched_Status := FALSE;
ELSIF Latch_Enable AND Alarm_Active THEN
    Latched_Status := TRUE;
END_IF;

(* Pass-through of the field contact (debounce not modeled). *)
DI_Out := DI_Raw;
Fault_State := FALSE;

ActiveIsA := NOT AlternateEnable;
IF Enable AND StartRequest AND NOT Inhibit THEN
    CmdPumpA := ActiveIsA AND NOT PumpA_Fault;
    CmdPumpB := (NOT ActiveIsA OR PumpA_Fault) AND NOT PumpB_Fault;
ELSE
    CmdPumpA := FALSE;
    CmdPumpB := FALSE;
END_IF;
IF ForcePumpA THEN
    CmdPumpA := Enable AND NOT Inhibit;
    CmdPumpB := FALSE;
END_IF;
IF ForcePumpB THEN
    CmdPumpA := FALSE;
    CmdPumpB := Enable AND NOT Inhibit;
END_IF;
SwitchedDueToDuty := DutyElapsed;
SwitchedDueToFailure := PumpA_Fault OR PumpB_Fault;
Alarm_FailedStart_A := PumpA_Fault;
Alarm_FailedStart_B := PumpB_Fault;
Alarm_NoAvailablePump := PumpA_Fault AND PumpB_Fault;

IF Inhibit OR Stop_Cmd THEN
    Motor_Start_Out := FALSE;
ELSIF Start_Cmd THEN
    Motor_Start_Out := TRUE;
END_IF;
FB_Running := Motor_Start_Out;
FB_HighSpeed := Motor_Start_Out AND Speed_High_Cmd;
FB_LowSpeed := Motor_Start_Out AND Speed_Low_Cmd AND NOT Speed_High_Cmd;
FB_Trip := FALSE;
Alarm_Speed_Error := Speed_High_Cmd AND Speed_Low_Cmd;

IF Inhibit OR Stop_Cmd THEN
    Motor_Start_Out := FALSE;
ELSIF Start_Cmd THEN
    Motor_Start_Out := TRUE;
END_IF;
FB_Running := Motor_Start_Out;
FB_Trip := FALSE;
Alarm_Start_Fail := FALSE;
Alarm_Stop_Fail := FALSE;

IF Inhibit OR Stop_Cmd THEN
    FB_Running := FALSE;
ELSIF Start_Cmd THEN
    FB_Running := TRUE;
END_IF;
IF FB_Running THEN
    Speed_Out := Speed_SP;
ELSE
    Speed_Out := 0.0;
END_IF;
FB_Ready := NOT Inhibit;
FB_Fault := FALSE;
FB_ActualSpeed := Speed_Out;
Alarm_Speed_Deviation := FALSE;
Alarm_Comm_Fail := FALSE;

PV_High_Alarm := PV > PV_High;
PV_Low_Alarm := PV < PV_Low;
Deviation_Alarm := ABS(SP - PV) > Deviation_Limit;
(* Bounded proportional control law (single-block, stateless). *)
IF Inhibit THEN
    XOUT := MV_MIN;
ELSIF AUTO THEN
    XOUT := LIMIT(MV_MIN, X0 + KP * (SP - PV), MV_MAX);
ELSE
    XOUT := X0;
END_IF;

IF PrimaryPV > 0.0 THEN
    ActiveRatio := SecondaryPV / PrimaryPV;
ELSE
    ActiveRatio := 0.0;
END_IF;
RatioErr := ActiveRatio - RatioSP;
IF Inhibit THEN
    SlaveSP := MV_MIN;
ELSIF Auto THEN
    SlaveSP := LIMIT(MV_MIN, PrimaryPV * RatioSP + Bias, MV_MAX);
ELSE
    SlaveSP := ManOut;
END_IF;

IF IN <= Split_Point THEN
    OUT1 := Output1_End;
    OUT2 := Output2_Start;
ELSE
    OUT1 := Output1_Start;
    OUT2 := Output2_End;
END_IF;

IF Inhibit THEN
    Valve_Position := Close_Limit;
ELSIF Manual_Mode THEN
    Valve_Position := LIMIT(Close_Limit, Manual_Position, Open_Limit);
ELSE
    Valve_Position := LIMIT(Close_Limit, Control_Signal, Open_Limit);
END_IF;
Feedback_Pos := Valve_Position;
Valve_Moving := FALSE;
Position_Error := FALSE;
Alarm := Inhibit;

IF Inhibit THEN
    Valve_Open_Out := FALSE;
    Valve_Close_Out := TRUE;
ELSE
    Valve_Open_Out := Open_Cmd AND NOT Close_Cmd;
    Valve_Close_Out := Close_Cmd OR NOT Open_Cmd;
END_IF;
FB_Opened := Valve_Open_Out;
FB_Closed := NOT Valve_Open_Out;
Alarm_Position_Error := FALSE;
Alarm_General := Inhibit;

Voted_Output := (Input1 + Input2 + Input3) / 3.0;
Sensor1_Fault := FALSE;
Sensor2_Fault := FALSE;
Sensor3_Fault := FALSE;
Alarm_Voting_Error := FALSE;
Healthy_Sensors_Count := 3;

FT_102(
    Raw_Signal := FT102_Raw_mA);
FIC_102(
    AUTO := TRUE,
    PV := FT_102.PV,
    SP := FFIC_102.SlaveSP,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    PV_Low := 10.0,
    Inhibit := AcidInhibit_OR);
FT_101(
    Raw_Signal := FT101_Raw_mA,
    PV_Low := 10.0,
    Scaling_Slope := 31.25,
    Scaling_Offset := -125.0,
    Alarm_Enable := TRUE);
LT_104(
    Raw_Signal := LT104_Raw_mA,
    PV_High := 90.0,
    PV_Low := 20.0,
    Alarm_Enable := TRUE);
TIC_103(
    PV := TIC103_Temperature_PV,
    PV_High := 190.0);
AcidInhibit_OR := LT_104.High_Alarm OR LT_104.Low_Alarm OR FT_101.Low_Alarm OR FIC_102.PV_Low_Alarm OR TIC_103.PV_High_Alarm;
FFIC_102(
    Auto := TRUE,
    PrimaryPV := FT_101.PV,
    SecondaryPV := FT_102.PV,
    RatioSP := 1.8,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    Inhibit := AcidInhibit_OR);
VS_107(
    Bool_In := VS107_Scrubber_Running_DI,
    Alarm_OnFalse := TRUE);
VS107_Fault_NOT := NOT VS_107.Bool_Out;
AmmoniaInhibit_OR := VS107_Fault_NOT OR TIC_103.PV_High_Alarm OR FT_101.Low_Alarm;
FIC_101(
    AUTO := FALSE,
    PV := FT_101.PV,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    X0 := 0.0,
    Inhibit := AmmoniaInhibit_OR);
PH_105(
    Raw_Signal := PH105_Raw_mA,
    PV_High := 7.3,
    PV_Low := 6.7,
    Alarm_Enable := TRUE);
FV_102(
    Control_Signal := FIC_102.XOUT,
    Inhibit := AcidInhibit_OR);
FV_101(
    Control_Signal := FIC_101.XOUT,
    Inhibit := AmmoniaInhibit_OR);

(* Outputs published to other sections / HMI. *)
FIC102_AcidFlow_SP_FromRatio := FFIC_102.SlaveSP;
FT101_AmmoniaFlow_PV := FT_101.PV;
LT104_ReactorLevel_PV := LT_104.PV;
PH105_ReactorPH_PV := PH_105.PV;
VS107_Scrubber_Permissive := VS_107.Bool_Out;

TT_103(
    PV_High := 210.0,
    PV_Low := 190.0,
    Alarm_Enable := TRUE);
TT_104(
    Alarm_Enable := TRUE);
PT_203(
    PV_High := 0.5,
    PV_Low := 0.2,
    Alarm_Enable := TRUE);
SensorsFault_OR := TT_103.General_Fault OR TT_104.General_Fault;
HS_204();
SteamTrip_OR := HS_204.DI_Out OR TT_103.High_Alarm;
TIC201_Inhibit1_OR := SteamTrip_OR OR SensorsFault_OR;
VacuumOutOfRange_OR := PT_203.High_Alarm OR PT_203.Low_Alarm;
TIC201_Inhibit_OR := TIC201_Inhibit1_OR OR VacuumOutOfRange_OR;
TIC_201(
    AUTO := TRUE,
    PV := TT_103.PV,
    SP := 198.0,
    MV_MIN := 1.0,
    MV_MAX := 96.0,
    X0 := 0.0,
    KP := 1.2,
    TR := 2.0,
    Deviation_Limit := 0.2,
    Inhibit := TIC201_Inhibit_OR);
FIC102_Inhibit_OR := TIC201_Inhibit1_OR OR TT_104.Low_Alarm;
FIC_102(
    AUTO := TRUE,
    PV := TT_104.PV,
    SP := TIC_201.XOUT,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    X0 := 0.0,
    KP := 3.5,
    TR := 0.3,
    Inhibit := FIC102_Inhibit_OR);
FV102_Inhibit_OR := TIC201_Inhibit1_OR OR TT_104.Low_Alarm;
XV_101(
    Inhibit := TIC201_Inhibit1_OR);
XVNotOpen_NOT := NOT XV_101.FB_Opened;
FV102_Final_OR := FV102_Inhibit_OR OR XVNotOpen_NOT;
FV_102(
    Control_Signal := FIC_102.XOUT,
    Manual_Mode := FALSE,
    Manual_Position := 0.0,
    Open_Limit := 100.0,
    Close_Limit := 0.0,
    Inhibit := FV102_Final_OR);
PV106_Inhibit_OR := VacuumOutOfRange_OR OR SensorsFault_OR;
PV_106(
    Open_Limit := 100.0,
    Close_Limit := 0.0,
    Inhibit := PV106_Inhibit_OR);
P205_Inhibit_OR := TIC_201.PV_Low_Alarm OR SensorsFault_OR;
P_205(
    Inhibit := P205_Inhibit_OR);
VS_206();

(* Outputs published to other sections / HMI. *)
TIC201_RSP_to_FIC102 := TIC_201.XOUT;

AT_303(
    Alarm_Enable := TRUE);
FT_301(
    Alarm_Enable := TRUE);
FV_301(
    Control_Signal := FIC_301.XOUT,
    Manual_Mode := FALSE,
    Open_Limit := 100.0,
    Close_Limit := 0.0,
    Inhibit := FV_301.Position_Error);
FICInterlock_OR := FT_301.High_Alarm OR FV_301.Position_Error OR FT_301.General_Fault OR FT_301.Low_Alarm;
GR_306(
    Alarm_OnTrue := FALSE,
    Alarm_OnFalse := TRUE,
    Latch_Enable := FALSE);
NotCollecting_NOT := NOT GR_306.Bool_Out;
RTD_302(
    PV_High := 200.0,
    PV_Low := 150.0,
    Alarm_Enable := TRUE);
VS_304();
CascadeInterlock_OR := RTD_302.High_Alarm OR AT_303.High_Alarm OR VS_304.General_Fault OR FT_301.General_Fault OR RTD_302.General_Fault OR NotCollecting_NOT OR RTD_302.Low_Alarm;
TIC_302(
    AUTO := TRUE,
    PV := RTD_302.PV,
    SP := 185.0,
    MV_MIN := 2.5,
    MV_MAX := 5.0,
    KP := 1.2,
    TR := 2.0,
    TD := 0.0,
    Deviation_Limit := 5.0,
    Inhibit := CascadeInterlock_OR);
FIC_301(
    AUTO := TRUE,
    PV := FT_301.PV,
    SP := TIC_302.XOUT,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    KP := 3.5,
    TR := 0.3,
    TD := 0.0,
    Deviation_Limit := 0.1,
    Inhibit := FICInterlock_OR);
PR_305();

(* Outputs published to other sections / HMI. *)
RTD302_BedTemp_PV := RTD_302.PV;
FT301_Flow_PV := FT_301.PV;
TIC302_RSP_to_FIC301 := TIC_302.XOUT;
FIC301_MV_Out_to_FV301 := FIC_301.XOUT;
AT303_Humidity_PV := AT_303.PV;
PR305_TowerPressure_PV := PR_305.PV;
VS304_Vibration_PV := VS_304.PV;

FT_402(
    Scaling_Slope := 1.0,
    Scaling_Offset := 0.0,
    Alarm_Enable := TRUE);
FT402_OutOfRange_OR := FT_402.High_Alarm OR FT_402.Low_Alarm;
FT402_Bad_OR := FT402_OutOfRange_OR OR FT_402.General_Fault;
TT_401(
    Scaling_Slope := 1.0,
    Scaling_Offset := 0.0,
    Alarm_Enable := TRUE);
TT401_OutOfRange_OR := TT_401.High_Alarm OR TT_401.Low_Alarm;
TT401_Bad_OR := TT401_OutOfRange_OR OR TT_401.General_Fault;
PermissiveFaults_OR1 := TT401_Bad_OR OR FT402_Bad_OR;
PSA_404();
PS_403();
PermissiveFaults_OR2 := PS_403.Bool_Out OR PSA_404.DI_Out;
CascadeInhibit_OR := PermissiveFaults_OR1 OR PermissiveFaults_OR2;
TIC_401(
    AUTO := TRUE,
    PV := TT_401.PV,
    SP := 45.0,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    KP := 1.2,
    TR := 2.0,
    PV_High := 50.0,
    PV_Low := 40.0,
    Deviation_Limit := 2.0,
    Inhibit := CascadeInhibit_OR);
TempError_SUB := 45.0 - TT_401.PV;
ErrorAbs_ABS := ABS(TempError_SUB);
Deadband_GT := (ErrorAbs_ABS > 0.5);
RSP_Scale_MUL := TIC_401.XOUT * 0.1;
RSP_Select_SEL := SEL(G := Deadband_GT, IN0 := FIC402_SP_Manual, IN1 := RSP_Scale_MUL);
FIC_402(
    AUTO := TRUE,
    PV := FT_402.PV,
    SP := RSP_Select_SEL,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    KP := 3.5,
    TR := 0.3,
    PV_High := 10.0,
    PV_Low := 0.5,
    Inhibit := CascadeInhibit_OR);
FV_402(
    Control_Signal := FIC_402.XOUT,
    Open_Limit := 100.0,
    Close_Limit := 0.0,
    Inhibit := CascadeInhibit_OR);
MP_405(
    Inhibit := CascadeInhibit_OR);

(* Outputs published to other sections / HMI. *)
TT401_CoolerOutletTemp_PV := TT_401.PV;
FT402_AntiCakingFlow_PV := FT_402.PV;
TIC401_RSP_to_FIC402 := TIC_401.XOUT;
FIC402_MV_to_FV402 := FIC_402.XOUT;

LT_501(
    PV_High := 90.0,
    PV_Low := 10.0,
    Alarm_Enable := TRUE);
WB_505(
    PV_Low := 100.0,
    Scaling_Slope := 6.25,
    Scaling_Offset := -25.0,
    Alarm_Enable := TRUE);
AP_503();
PRV_502();
AP503_NotActive_NOT := NOT AP_503.FB_Opened;
PRV502_NotClosed_NOT := NOT PRV_502.FB_Closed;
RIC506_Inhibit_OR := AP503_NotActive_NOT OR PRV502_NotClosed_NOT OR WB_505.Low_Alarm;
LT501_Above80_GT := (LT_501.PV > 80.0);
RatioSP_HighTerm_MULT := BOOL_TO_REAL(LT501_Above80_GT) * 1.0;
LT501_Below20_LT := (LT_501.PV < 20.0);
RatioSP_LowTerm_MULT := BOOL_TO_REAL(LT501_Below20_LT) * 2.0;
RatioSP_HL_ADD := RatioSP_HighTerm_MULT + RatioSP_LowTerm_MULT;
Level_OutOfRange_OR := LT501_Above80_GT OR LT501_Below20_LT;
LevelInNominal_NOT := NOT Level_OutOfRange_OR;
RatioSP_NominalBias_ADD := 1.5 + Ratio_Bias_Manual;
RatioSP_NominalTerm_MULT := BOOL_TO_REAL(LevelInNominal_NOT) * RatioSP_NominalBias_ADD;
RatioSP_Final_ADD := RatioSP_HL_ADD + RatioSP_NominalTerm_MULT;
FIC_507(
    AUTO := TRUE,
    PV := SC_504.FB_ActualSpeed,
    SP := RIC_506.SlaveSP,
    MV_MIN := 0.0,
    MV_MAX := 100.0);
SC504_Shutdown_OR := RIC506_Inhibit_OR OR LT_501.Low_Alarm;
SC_504(
    Speed_SP := FIC_507.XOUT,
    Accel_Ramp := T#2s,
    Decel_Ramp := T#2s,
    Inhibit := SC504_Shutdown_OR);
RIC_506(
    Auto := TRUE,
    PrimaryPV := WB_505.PV,
    SecondaryPV := SC_504.FB_ActualSpeed,
    RatioSP := RatioSP_Final_ADD,
    Bias := 0.0,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    Inhibit := RIC506_Inhibit_OR);

(* Outputs published to other sections / HMI. *)
LT501_Level_Pct := LT_501.PV;
WB505_Flow_Pct := WB_505.PV;
RIC506_SC504_FlowSP := RIC_506.SlaveSP;
